public static void main(String[] args) {
    PrintWriter out = new PrintWriter(System.out);
    InputReader sc = new InputReader(System.in);
    long n = sc.nextLong();
    long ans = 0;
    for (long i = 1; i <= n; i++) {
        long sumOfDigits = 0;
        long temp = i;
        while (temp > 0) {
            sumOfDigits += temp % 10;
            temp /= 10;
        }
        if (i % sumOfDigits == 0) {
            ans++;
        }
    }
    System.out.println(ans);
}
